<?php
declare(strict_types=1);require __DIR__.'/config.php';require_admin();if(function_exists('ensure_branch_schema'))ensure_branch_schema();require __DIR__.'/patient-layout.php';$pdo=db();$driver=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME);
$pdo->exec($driver==='sqlite'?"CREATE TABLE IF NOT EXISTS employees(id INTEGER PRIMARY KEY AUTOINCREMENT,full_name TEXT NOT NULL,email TEXT NULL UNIQUE,start_date DATE NOT NULL,end_date DATE NULL,job_title TEXT NOT NULL,birth_date DATE NULL,branch_id INTEGER NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP)":"CREATE TABLE IF NOT EXISTS employees(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(190) NOT NULL,email VARCHAR(190) NULL UNIQUE,start_date DATE NOT NULL,end_date DATE NULL,job_title VARCHAR(190) NOT NULL,birth_date DATE NULL,branch_id INT UNSIGNED NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$employeeColumns=$driver==='sqlite'?$pdo->query('PRAGMA table_info(employees)')->fetchAll(PDO::FETCH_COLUMN,1):$pdo->query('SHOW COLUMNS FROM employees')->fetchAll(PDO::FETCH_COLUMN,0);if(!in_array('birth_date',$employeeColumns,true))$pdo->exec($driver==='sqlite'?'ALTER TABLE employees ADD COLUMN birth_date DATE NULL':'ALTER TABLE employees ADD COLUMN birth_date DATE NULL AFTER job_title');if(!in_array('branch_id',$employeeColumns,true))$pdo->exec($driver==='sqlite'?'ALTER TABLE employees ADD COLUMN branch_id INTEGER NULL':'ALTER TABLE employees ADD COLUMN branch_id INT UNSIGNED NULL AFTER birth_date');$branches=$pdo->query('SELECT id,name,active FROM branches ORDER BY active DESC,name')->fetchAll();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($action==='delete'&&$id){$pdo->prepare('DELETE FROM employees WHERE id=?')->execute([$id]);$message='Çalışan silindi.';}else{$name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$start=trim((string)($_POST['start_date']??''));$end=trim((string)($_POST['end_date']??''));$job=trim((string)($_POST['job_title']??''));$birth=trim((string)($_POST['birth_date']??''));$branchId=(int)($_POST['branch_id']??0);$birthValid=$birth===''||(preg_match('/^(\d{4})-(\d{2})-(\d{2})$/',$birth,$birthParts)&&checkdate((int)$birthParts[2],(int)$birthParts[3],(int)$birthParts[1]));if($name===''||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||$start===''||$job==='')$error='Zorunlu alanları geçerli bilgilerle doldurun.';elseif(!$birthValid)$error='Geçerli bir doğum tarihi seçin.';elseif($end!==''&&$end<$start)$error='Çıkış tarihi giriş tarihinden önce olamaz.';else try{if($id){$pdo->prepare('UPDATE employees SET full_name=?,email=?,start_date=?,end_date=?,job_title=?,birth_date=?,branch_id=? WHERE id=?')->execute([$name,$email?:null,$start,$end?:null,$job,$birth?:null,$branchId?:null,$id]);$message='Çalışan güncellendi.';}else{$pdo->prepare('INSERT INTO employees(full_name,email,start_date,end_date,job_title,birth_date,branch_id) VALUES(?,?,?,?,?,?,?)')->execute([$name,$email?:null,$start,$end?:null,$job,$birth?:null,$branchId?:null]);$message='Çalışan eklendi.';}}catch(PDOException $e){$error='Çalışan kaydedilemedi. Girilen bilgileri kontrol edin.';}}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM employees WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$employees=$pdo->query("SELECT e.*,b.name branch_name FROM employees e LEFT JOIN branches b ON b.id=e.branch_id ORDER BY CASE WHEN e.start_date<=CURRENT_DATE AND (e.end_date IS NULL OR e.end_date='' OR e.end_date>=CURRENT_DATE) THEN 0 ELSE 1 END,e.start_date DESC,e.id DESC")->fetchAll();patient_header('Ayarlar - Çalışanlar','settings');?>
<main class="patient-container employee-page"><nav class="settings-tabs"><a href="<?=url('admin.php')?>">Kullanıcı Yönetimi</a><a href="<?=url('branches.php')?>">Şubeler</a><a class="active" href="<?=url('employees.php')?>">Çalışanlar</a></nav><?php if($message):?><div class="notice success"><?=e($message)?></div><?php endif?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><details class="employee-card employee-accordion"<?=($edit||$error!=='')?' open':''?>><summary><span><h1><?=$edit?'Çalışanı Düzenle':'Yeni Çalışan'?></h1><p>Çalışan bilgilerini ve görev durumlarını yönetin.</p></span><i class="employee-chevron" aria-hidden="true"></i></summary><form method="post" class="employee-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>Ad Soyad<input name="full_name" value="<?=e($edit['full_name']??'')?>" required></label><label>E-posta<input type="email" name="email" value="<?=e($edit['email']??'')?>"></label><label>Giriş Tarihi<input type="date" name="start_date" value="<?=e($edit['start_date']??date('Y-m-d'))?>" required></label><label>Çıkış Tarihi<input type="date" name="end_date" value="<?=e($edit['end_date']??'')?>"></label><label>Görevi<input name="job_title" value="<?=e($edit['job_title']??'')?>" required></label><label>Doğum Günü<input type="date" name="birth_date" value="<?=e($edit['birth_date']??'')?>"></label><label class="employee-branch">Şube<select name="branch_id"><option value="">Seçiniz</option><?php foreach($branches as $branch):?><option value="<?=(int)$branch['id']?>" <?=((int)($edit['branch_id']??0)===(int)$branch['id'])?'selected':''?>><?=e($branch['name'])?><?=$branch['active']?'':' (Pasif)'?></option><?php endforeach?></select></label><div class="actions"><button>Kaydet</button><?php if($edit):?><a href="<?=url('employees.php')?>">İptal</a><?php endif?></div></form></details><section class="employee-card"><header><h2>Çalışan Listesi</h2><p><?=count($employees)?> kayıt</p></header><div class="table-scroll"><table><thead><tr><th>Ad Soyad</th><th>E-posta</th><th>Giriş Tarihi</th><th>Çıkış Tarihi</th><th>Görevi</th><th>Şube</th><th>Doğum Günü</th><th>İşlemler</th></tr></thead><tbody><?php foreach($employees as $x):?><tr><td><b><?=e($x['full_name'])?></b></td><td><?=e($x['email'])?></td><td><?=format_date_tr($x['start_date'])?></td><td><?=$x['end_date']?format_date_tr($x['end_date']):'—'?></td><td><?=e($x['job_title'])?></td><td><?=e($x['branch_name']??'—')?></td><td><?=$x['birth_date']?format_date_tr($x['birth_date']):'—'?></td><td><a class="edit employee-icon-action employee-icon-edit" href="<?=url('employees.php?edit='.(int)$x['id'])?>" title="Düzenle" aria-label="<?=e($x['full_name'])?> çalışanını düzenle"><i class="ti tabler-edit" aria-hidden="true"></i></a><form method="post" onsubmit="return confirm('Bu çalışan silinsin mi?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$x['id']?>"><button class="delete employee-icon-action employee-icon-delete" title="Sil" aria-label="<?=e($x['full_name'])?> çalışanını sil"><i class="ti tabler-trash" aria-hidden="true"></i></button></form></td></tr><?php endforeach?><?php if(!$employees):?><tr><td colspan="8">Henüz çalışan kaydı bulunmuyor.</td></tr><?php endif?></tbody></table></div></section></main>
<style>.employee-page{max-width:1180px;margin:auto;padding:28px 20px}.settings-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}.settings-tabs a{padding:11px 16px;border-radius:7px;text-decoration:none;color:#16883d;background:#e8f7ed;font-weight:700}.settings-tabs a.active{background:#19a94b;color:#fff}.employee-card{background:var(--card,#fff);border:1px solid var(--line,#ddd);border-radius:9px;margin-bottom:22px;overflow:hidden}.employee-card>header,.employee-accordion>summary{padding:20px 24px;border-bottom:1px solid var(--line,#ddd)}.employee-card h1,.employee-card h2{margin:0 0 5px}.employee-card header p,.employee-accordion summary p{margin:0;color:var(--muted)}.employee-accordion>summary{position:relative;display:flex!important;align-items:center;padding-right:64px;cursor:pointer;list-style:none;user-select:none}.employee-accordion>summary::-webkit-details-marker{display:none}.employee-accordion>summary::marker{display:none;content:""}.employee-chevron{position:absolute;right:24px;top:50%;display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;font-style:normal;font-size:20px;font-weight:500;line-height:1;transform:translateY(-50%);transition:transform .2s ease}.employee-chevron::before{content:">"}.employee-accordion[open] .employee-chevron{transform:translateY(-50%) rotate(90deg)}.employee-accordion:not([open])>summary{border-bottom:0}.employee-form{display:grid;grid-template-columns:repeat(2,1fr);gap:18px 24px;padding:24px}.employee-form label{display:flex;flex-direction:column;gap:7px}.employee-form input,.employee-form select{height:42px;border:1px solid #d4d5dd;border-radius:6px;padding:0 11px;background:transparent;color:inherit}.employee-branch{grid-column:2}.actions{grid-column:1/-1;display:flex;gap:12px;align-items:center}.employee-form button,.edit,.delete{display:inline-flex;border:0;border-radius:6px;padding:9px 13px;background:#19a94b;color:#fff;text-decoration:none;font-weight:700}.delete{background:#d94b4b}.table-scroll{overflow:auto}.employee-card table{width:100%;min-width:850px;border-collapse:collapse}.employee-card th,.employee-card td{padding:13px 18px;text-align:left;border-bottom:1px solid var(--line,#ddd);white-space:nowrap}.employee-card td form{display:inline}.notice{padding:12px 15px;margin-bottom:16px;border-radius:7px}.notice.success{background:#dff5e6;color:#147238}.notice.error{background:#ffe2e2;color:#9b2020}[data-theme=dark] .employee-card{background:#2f3349;color:#fff}@media(max-width:700px){.employee-form{grid-template-columns:1fr}.employee-branch,.actions{grid-column:auto}}</style><?php patient_footer();?>
